"""Embeds firmware/web/dashboard.html into a C header. Run after editing the page."""
from pathlib import Path

root = Path(__file__).resolve().parents[1] / "firmware"
html = (root / "web" / "dashboard.html").read_text(encoding="utf8")
assert ')HTMLPAGE"' not in html
(root / "src" / "dashboard_html.h").write_text(
    "// Generated by tools/embed_web.py from firmware/web/dashboard.html. Do not edit.\n#pragma once\n"
    '#include <pgmspace.h>\n\nstatic const char DASHBOARD_HTML[] PROGMEM = R"HTMLPAGE(' + html + ')HTMLPAGE";\n',
    encoding="utf8",
)
